export function applyDiscount(amount, percent) {
  if (!Number.isFinite(amount) || amount < 0) {
    throw new RangeError('non-negative finite amount required');
  }
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
    throw new RangeError('finite percent between 0 and 100 required');
  }
  return amount * (1 - percent / 100);
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { applyDiscount } from '../src/discount.mjs';

test('discount applies the specified percentage without rounding to cents', () => {
  assert.equal(applyDiscount(200, 25), 150);
  assert.equal(applyDiscount(12.345, 10), 12.345 * (1 - 10 / 100));
});

test('discount handles zero amount and percentage boundaries', () => {
  assert.equal(applyDiscount(200, 0), 200);
  assert.equal(applyDiscount(200, 100), 0);
  for (const percent of [0, 25, 100]) {
    assert.equal(applyDiscount(0, percent), 0);
  }
});

test('discount rejects invalid amounts with RangeError without coercion', () => {
  for (const amount of [-1, NaN, Infinity, -Infinity, '200', null, undefined, true, {}, 200n]) {
    assert.throws(() => applyDiscount(amount, 25), RangeError);
  }
});

test('discount rejects invalid percentages with RangeError without coercion', () => {
  for (const percent of [-1, 101, NaN, Infinity, -Infinity, '25', null, undefined, true, {}, 25n]) {
    assert.throws(() => applyDiscount(200, percent), RangeError);
  }
});
